import { forwardRef, useCallback, useMemo, useRef } from 'react';
import { useControllableState } from '../../hooks/useControllableState';

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface SegmentedControlItem {
  value: string;
  label?: string;
  icon?: string;
  isDisabled?: boolean;
}

export interface SegmentedControlChangeDetail {
  value: string;
  previousValue: string | null;
}

export interface ArvoSegmentedControlProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'onChange' | 'defaultValue'> {
  items: SegmentedControlItem[];
  value?: string | null;
  defaultValue?: string | null;
  variant?: 'primary' | 'secondary';
  size?: 'sm' | 'lg';
  isIconOnly?: boolean;
  isDisabled?: boolean;
  isLoading?: boolean;
  ariaLabel: string;
  onChange?: (detail: SegmentedControlChangeDetail) => void;
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

const ArvoSegmentedControl = forwardRef<HTMLDivElement, ArvoSegmentedControlProps>(
  function ArvoSegmentedControl(
    {
      items,
      value: valueProp,
      defaultValue = null,
      variant = 'primary',
      size = 'lg',
      isIconOnly = false,
      isDisabled = false,
      isLoading = false,
      ariaLabel,
      onChange,
      className,
      ...rest
    },
    ref,
  ) {
    const [value, setValue] = useControllableState(valueProp, defaultValue);
    const optionRefs = useRef<(HTMLButtonElement | null)[]>([]);

    const classes = useMemo(
      () =>
        [
          'arvo-seg-ctrl',
          `arvo-seg-ctrl--${variant}`,
          `arvo-seg-ctrl--${size}`,
          isIconOnly && 'arvo-seg-ctrl--icon-only',
          isDisabled && 'is-disabled',
          isLoading && 'loading',
          className,
        ]
          .filter(Boolean)
          .join(' '),
      [variant, size, isIconOnly, isDisabled, isLoading, className],
    );

    const select = useCallback(
      (next: string) => {
        if (isDisabled || isLoading) return;
        if (next === value) return;
        const target = items.find((it) => it.value === next);
        if (!target || target.isDisabled) return;
        const previous = (value as string | null) ?? null;
        setValue(next);
        onChange?.({ value: next, previousValue: previous });
      },
      [isDisabled, isLoading, items, value, setValue, onChange],
    );

    const handleKeyDown = useCallback(
      (event: React.KeyboardEvent<HTMLDivElement>) => {
        if (isDisabled || isLoading) return;
        const { key } = event;
        const isPrev = key === 'ArrowLeft' || key === 'ArrowUp';
        const isNext = key === 'ArrowRight' || key === 'ArrowDown';
        const isHome = key === 'Home';
        const isEnd = key === 'End';
        const isActivate = key === 'Enter' || key === ' ';

        if (!isPrev && !isNext && !isHome && !isEnd && !isActivate) return;

        const enabled = items
          .map((item, idx) => ({ item, idx, el: optionRefs.current[idx] }))
          .filter(({ item, el }) => el && !item.isDisabled);

        if (enabled.length === 0) return;

        const activeEl = document.activeElement as HTMLButtonElement | null;
        const currentIdx = enabled.findIndex(({ el }) => el === activeEl);

        if (isActivate) {
          if (currentIdx === -1) return;
          event.preventDefault();
          select(enabled[currentIdx].item.value);
          return;
        }

        event.preventDefault();
        let targetIdx: number;
        if (isHome) targetIdx = 0;
        else if (isEnd) targetIdx = enabled.length - 1;
        else if (isNext) targetIdx = currentIdx === -1 ? 0 : (currentIdx + 1) % enabled.length;
        else targetIdx = currentIdx === -1 ? enabled.length - 1 : (currentIdx - 1 + enabled.length) % enabled.length;

        const target = enabled[targetIdx];
        if (!target?.el) return;
        target.el.focus();
        select(target.item.value);
      },
      [isDisabled, isLoading, items, select],
    );

    const enabledItems = useMemo(
      () => items.filter((it) => !it.isDisabled),
      [items],
    );
    const focusedItemValue = useMemo(() => {
      if (typeof value === 'string') {
        const matched = enabledItems.find((it) => it.value === value);
        if (matched) return matched.value;
      }
      return enabledItems[0]?.value ?? null;
    }, [enabledItems, value]);

    return (
      <div
        ref={ref}
        className={classes}
        role="radiogroup"
        aria-label={ariaLabel}
        aria-busy={isLoading || undefined}
        aria-disabled={isDisabled || undefined}
        onKeyDown={handleKeyDown}
        {...rest}
      >
        {items.map((item, index) => {
          const isItemDisabled = isDisabled || (item.isDisabled ?? false);
          const isChecked = value === item.value;
          const tabIdx = item.value === focusedItemValue && !isItemDisabled ? 0 : -1;
          const refCallback = (el: HTMLButtonElement | null) => {
            optionRefs.current[index] = el;
          };
          const labelText = item.label ?? item.value;

          return (
            <button
              key={item.value}
              ref={refCallback}
              type="button"
              role="radio"
              className="arvo-seg-ctrl__opt"
              aria-checked={isChecked}
              aria-disabled={isItemDisabled || undefined}
              aria-label={isIconOnly ? labelText : undefined}
              tabIndex={tabIdx}
              disabled={isItemDisabled}
              data-value={item.value}
              onClick={() => select(item.value)}
            >
              {item.icon && (
                <span
                  className={`arvo-seg-ctrl__ico o9con o9con-${item.icon}`}
                  aria-hidden="true"
                />
              )}
              {!isIconOnly && item.label && (
                <span className="arvo-seg-ctrl__lbl">{item.label}</span>
              )}
            </button>
          );
        })}
      </div>
    );
  },
);

export default ArvoSegmentedControl;
export { ArvoSegmentedControl };
